  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    node_map = {n['id']: n for n in nodes}
    children_map = {}
    for n in nodes:
        children_map.setdefault(n['id'], [])
        p = n['parent']
        if p is not None:
            children_map.setdefault(p, []).append(n['id'])

    # initial retained set
    retained = set(node_map.keys())
    removed_order = []

    # Sort nodes by depth descending, then by id ascending for tie-break
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    for n in sorted_nodes:
        nid = n['id']
        # never remove root, required symbol, or node with retained children
        if n['parent'] is None:
            continue
        if n['symbol'] in required_symbols:
            continue
        if not n.get('removable', False):
            continue
        # check if any child is still retained
        has_retained_child = any(cid in retained for cid in children_map.get(nid, []))
        if has_retained_child:
            continue
        # simulate removal
        candidate_retained = retained - {nid}
        # check all required symbols still present
        ok = True
        for sym in required_symbols:
            found = any(node_map[cid]['symbol'] == sym for cid in candidate_retained)
            if not found:
                ok = False
                break
        if ok:
            removed_order.append(nid)
            retained = candidate_retained

    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_sorted
    }
